// generate_conflict_report.rs - Generate symbol conflict report
// Generated by step4_bootstrap - Symbol Conflict Report

use split_decls_genesis::{
    find_rust_files_in_dependency_fast, extract_all_symbols_from_file_fast,
    get_rustc_dependencies, Symbol
};
use std::collections::HashMap;
use serde_json;

#[derive(Debug, Clone)]
struct ConflictReport {
    total_symbols: usize,
    conflicts_detected: usize,
    qualified_symbols: usize,
    conflicts: Vec<SymbolConflict>,
}

#[derive(Debug, Clone)]
struct SymbolConflict {
    symbol_name: String,
    crates: Vec<String>,
    winner: String,
    overwritten: Vec<String>,
}

fn main() {
    println!("🔍 Generating symbol conflict report...");
    
    let rustc_deps = get_rustc_dependencies().unwrap_or_default();
    let mut all_symbols: HashMap<String, Symbol> = HashMap::new();
    let mut conflicts: Vec<SymbolConflict> = Vec::new();
    let mut conflict_count = 0;
    
    for dep in &rustc_deps {
        let rust_files = find_rust_files_in_dependency_fast(&dep.path);
        println!("📦 {}: {} files", dep.name, rust_files.len());
        
        for file in rust_files {
            if let Ok(symbols) = extract_all_symbols_from_file_fast(&file.to_string_lossy(), &dep.name) {
                for symbol in symbols {
                    // Track conflicts
                    if let Some(existing) = all_symbols.get(&symbol.name) {
                        conflict_count += 1;
                        
                        // Find or create conflict record
                        let mut conflict = conflicts.iter_mut()
                            .find(|c| c.symbol_name == symbol.name)
                            .cloned()
                            .unwrap_or_else(|| SymbolConflict {
                                symbol_name: symbol.name.clone(),
                                crates: vec![existing.crate_name.clone()],
                                winner: existing.crate_name.clone(),
                                overwritten: vec![],
                            });
                        
                        if !conflict.crates.contains(&symbol.crate_name) {
                            conflict.crates.push(symbol.crate_name.clone());
                        }
                        
                        // Determine winner and overwritten
                        if symbol.crate_name == "std" && existing.crate_name != "std" {
                            conflict.overwritten.push(format!("{}::{}", existing.crate_name, existing.name));
                            conflict.winner = "std".to_string();
                            
                            // Save overwritten with qualified name
                            let qualified_key = format!("{}::{}", existing.crate_name, existing.name);
                            all_symbols.insert(qualified_key, existing.clone());
                            all_symbols.insert(symbol.name.clone(), symbol);
                        } else if existing.crate_name == "std" && symbol.crate_name != "std" {
                            conflict.overwritten.push(format!("{}::{}", symbol.crate_name, symbol.name));
                            // Keep existing std version
                            let qualified_key = format!("{}::{}", symbol.crate_name, symbol.name);
                            all_symbols.insert(qualified_key, symbol);
                        } else {
                            // Save both with qualified names
                            let existing_key = format!("{}::{}", existing.crate_name, existing.name);
                            let symbol_key = format!("{}::{}", symbol.crate_name, symbol.name);
                            all_symbols.insert(existing_key, existing.clone());
                            all_symbols.insert(symbol_key, symbol);
                        }
                        
                        // Update or add conflict
                        if let Some(pos) = conflicts.iter().position(|c| c.symbol_name == conflict.symbol_name) {
                            conflicts[pos] = conflict;
                        } else {
                            conflicts.push(conflict);
                        }
                    } else {
                        all_symbols.insert(symbol.name.clone(), symbol);
                    }
                }
            }
        }
    }
    
    // Count qualified symbols
    let qualified_count = all_symbols.keys()
        .filter(|k| k.contains("::"))
        .count();
    
    let report = ConflictReport {
        total_symbols: all_symbols.len(),
        conflicts_detected: conflicts.len(),
        qualified_symbols: qualified_count,
        conflicts: conflicts.clone(),
    };
    
    println!("\n📊 SYMBOL CONFLICT REPORT:");
    println!("  📦 Total symbols: {}", report.total_symbols);
    println!("  ⚠️  Conflicts detected: {}", report.conflicts_detected);
    println!("  🏷️  Qualified symbols: {}", report.qualified_symbols);
    
    println!("\n🔍 TOP CONFLICTS:");
    for (i, conflict) in conflicts.iter().take(10).enumerate() {
        println!("  {}. '{}' found in {} crates", i+1, conflict.symbol_name, conflict.crates.len());
        println!("     Winner: {}", conflict.winner);
        println!("     Crates: {}", conflict.crates.join(", "));
        if !conflict.overwritten.is_empty() {
            println!("     Overwritten: {}", conflict.overwritten.join(", "));
        }
    }
    
    // Export detailed report
    let report_json = serde_json::json!({
        "summary": {
            "total_symbols": report.total_symbols,
            "conflicts_detected": report.conflicts_detected,
            "qualified_symbols": report.qualified_symbols
        },
        "conflicts": conflicts.iter().map(|c| serde_json::json!({
            "symbol_name": c.symbol_name,
            "crates": c.crates,
            "winner": c.winner,
            "overwritten": c.overwritten
        })).collect::<Vec<_>>()
    });
    
    let json_str = serde_json::to_string_pretty(&report_json).unwrap();
    std::fs::write("symbol_conflicts.json", json_str).unwrap();
    
    println!("\n📄 Exported symbol_conflicts.json");
    
    // Show some qualified symbols
    println!("\n🏷️  Sample qualified symbols:");
    let qualified_symbols: Vec<_> = all_symbols.keys()
        .filter(|k| k.contains("::"))
        .take(10)
        .collect();
    
    for (i, symbol) in qualified_symbols.iter().enumerate() {
        if let Some(sym_data) = all_symbols.get(*symbol) {
            println!("  {}. {} ({})", i+1, symbol, sym_data.source_file);
        }
    }
}
